const input = $input.item.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const data = body.data && typeof body.data === 'object' ? body.data : body;
const key = (v) => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const text = (v) => Array.isArray(v) ? v.map(text).filter(Boolean).join(', ') : (v == null ? '' : String(v).trim());
const flat = {};
for (const obj of [input, body, data]) {
  if (!obj || typeof obj !== 'object') continue;
  for (const [k, v] of Object.entries(obj)) {
    if (v == null || typeof v !== 'object') flat[key(k)] = text(v);
  }
  for (const field of (obj.fields || obj.answers || [])) {
    const value = text(field.value ?? field.answer ?? field.text ?? field.response);
    for (const label of [field.key, field.label, field.name, field.title]) {
      if (label && value) flat[key(label)] = value;
    }
  }
}
const pick = (...labels) => labels.map(key).map((k) => flat[k]).find(Boolean) || '';
const firstName = pick('first_name', 'first name', 'firstname');
const lastName = pick('last_name', 'last name', 'lastname');
const email = pick('email', 'work email').toLowerCase().trim();
const company = pick('company', 'company name');
const role = pick('role', 'job title');
const messageRaw = pick('message_raw', 'how can we help', 'message', 'description');
const messageClean = messageRaw.replace(/\s+/g, ' ').trim();
const source = pick('source') || 'tally_form';
const receivedAt = pick('received_at', 'submitted at', 'created at') || new Date().toISOString();
const submissionId = pick('submission_id', 'submission id', 'response id', 'id');
const errors = [];
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('A valid email is required.');
if (!messageClean) errors.push('A message is required.');
const fingerprint = `${submissionId}|${email}|${messageClean.toLowerCase()}`;
let hash = 5381;
for (const char of fingerprint) hash = ((hash << 5) + hash) ^ char.charCodeAt(0);
const leadId = submissionId || `lead_${(hash >>> 0).toString(36)}`;
return {
  json: {
    workflow: 'OpsPilot - Main Intake',
    accepted: errors.length === 0,
    lead_id: leadId,
    source,
    received_at: receivedAt,
    full_name: [firstName, lastName].filter(Boolean).join(' '),
    first_name: firstName,
    last_name: lastName,
    email,
    company,
    role,
    message_raw: messageRaw,
    message_clean: messageClean,
    validation_status: errors.length ? 'Needs Review' : 'Valid',
    validation_errors: errors,
    human_review_required: true,
  }
};

const searchRaw = $input.item.json;
const lead = $('Normalize And Validate').item.json;
let contacts = [];
if (Array.isArray(searchRaw)) {
  contacts = searchRaw;
} else if (searchRaw && Array.isArray(searchRaw.results)) {
  contacts = searchRaw.results;
} else if (searchRaw && searchRaw.id) {
  contacts = [searchRaw];
}
const existing = contacts.length > 0 ? contacts[0] : null;
return {
  json: {
    ...lead,
    hubspot_contact_exists: !!existing,
    hs_contact_id: existing ? (existing.id || null) : null,
    duplicate_risk: !!existing,
    hs_existing_properties: existing ? (existing.properties || {}) : null,
  }
};

const dedup = $('Attach Dedup Context').item.json;
const raw = $input.item.json;
const VALID_CATEGORIES = ['Demo Request', 'Support Request', 'Partnership', 'Incomplete', 'Spam / Irrelevant', 'Needs Review'];
const VALID_PRIORITIES = ['Urgent', 'Hot', 'Warm', 'Cold', 'Needs Review'];
const VALID_FLAGS = ['duplicate_risk', 'urgent_escalation', 'incomplete_data', 'high_value_prospect', 'existing_customer_signal', 'partnership_signal'];
let rawText = '';
try {
  if (raw.content && Array.isArray(raw.content)) {
    rawText = raw.content.map(c => c.text || '').join('');
  } else if (typeof raw.content === 'string') {
    rawText = raw.content;
  } else if (raw.text) {
    rawText = raw.text;
  } else {
    rawText = JSON.stringify(raw);
  }
} catch(e) { rawText = ''; }
const stopReason = raw.stop_reason || raw.stopReason || '';
const tokenError = stopReason === 'max_tokens';
let classification = {};
let processingError = null;
try {
  if (tokenError) throw new Error('max_tokens: response truncated');
  const match = rawText.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON object found in Claude response');
  classification = JSON.parse(match[0]);
  if (!VALID_CATEGORIES.includes(classification.category)) throw new Error('Invalid category: ' + classification.category);
  if (!VALID_PRIORITIES.includes(classification.priority)) throw new Error('Invalid priority: ' + classification.priority);
  if (Array.isArray(classification.flags)) {
    classification.flags = classification.flags.filter(f => VALID_FLAGS.includes(f));
  } else {
    classification.flags = [];
  }
} catch(e) {
  processingError = e.message;
  classification = {
    category: 'Needs Review',
    priority: 'Needs Review',
    confidence: 'Low',
    summary: 'AI classification failed. Manual review required.',
    intent_signals: [],
    missing_fields: [],
    recommended_action: 'Review the message manually and classify before routing.',
    crm_note: (dedup.full_name || dedup.email) + ' submitted a message via ' + dedup.source + '. AI classification failed. Manual review required.',
    draft_reply: 'Thank you for your message. A team member will review your request and follow up shortly.',
    flags: [],
    human_review_required: true,
  };
}
return {
  json: {
    ...dedup,
    ...classification,
    human_review_required: true,
    processing_error: processingError || null,
    airtable_status: processingError ? 'Error' : 'Processed',
  }
};

const hubspot = $input.item.json;
const dedup = $('Attach Dedup Context').item.json;
const classification = $('Parse And Validate Claude Response').item.json;
const hsContactId = hubspot.id || (hubspot.properties && hubspot.properties.hs_object_id) || dedup.hs_contact_id;
const hsAction = dedup.hubspot_contact_exists ? 'updated' : 'created';
return {
  json: {
    ...dedup,
    ...classification,
    hs_contact_id: hsContactId,
    hs_action: hsAction,
    hs_deal_id: null,
    hs_note_id: null,
    hs_task_id: null,
    airtable_status: dedup.hubspot_contact_exists
      ? 'Duplicate Merged'
      : (classification.processing_error ? 'Error' : 'Processed'),
  }
};

// Consolidate data from whichever branch was taken
let norm = null, claude = null, restore = null;
try { norm = $('Normalize And Validate').item.json; } catch(e) {}
try { claude = $('Parse And Validate Claude Response').item.json; } catch(e) {}
try { restore = $('Restore Context').item.json; } catch(e) {}
const base = restore || claude || norm || {};
let hs_contact_id = String(base.hs_contact_id || '');
let hs_deal_id = String(base.hs_deal_id || '');
try {
  const deal = $('HubSpot Create Deal').item.json;
  if (deal && (deal.id || deal.dealId)) hs_deal_id = String(deal.id || deal.dealId);
} catch(e) {}
let status = 'Processed';
if (base.processing_error) status = 'Error';
else if (base.accepted === false) status = 'Needs Review';
else if (base.airtable_status) status = base.airtable_status;
const priority = base.priority || '';
const category = base.category || '';
const owner = (priority === 'Urgent' || priority === 'Hot') ? 'AE' : (category === 'Incomplete' ? 'SDR' : 'Ops');
const hs_contact_url = hs_contact_id ? 'https://app-eu1.hubspot.com/contacts/__HUBSPOT_PORTAL_ID__/contact/' + hs_contact_id : '';
return { json: {
  lead_id: base.lead_id || '',
  received_at: base.received_at || '',
  source: base.source || 'tally_form',
  full_name: base.full_name || '',
  email: base.email || '',
  company: base.company || '',
  category: category,
  priority: priority,
  hs_action: base.hs_action || '',
  hs_contact_id: hs_contact_id,
  hs_deal_id: hs_deal_id,
  hs_contact_url: hs_contact_url,
  summary: base.summary || '',
  draft_reply: base.draft_reply || '',
  confidence: base.confidence || '',
  flags: Array.isArray(base.flags) ? base.flags : [],
  processing_error: base.processing_error || null,
  status: status,
  owner: owner,
}};

